#!/usr/bin/env node

import {
  chmodSync,
  copyFileSync,
  existsSync,
  mkdirSync,
  readFileSync,
  renameSync,
  statSync,
  writeFileSync,
} from "node:fs"
import { homedir } from "node:os"
import { dirname, join, resolve } from "node:path"
import { createInterface } from "node:readline/promises"
import { fileURLToPath } from "node:url"

function usage(exitCode = 0) {
  console.log(`Usage: backeer-opencode [command] [options]

Commands:
  status              Read this project's running Backeer report without model execution
  configure           Securely prompt for and store the Backeer ingest token
  install             Install the side-loaded plugin (default)

Options:
  --config-dir PATH   OpenCode config directory (default: XDG_CONFIG_HOME/opencode)
  --token-file PATH   Read the token from PATH when using install
  --token-stdin       Read the token from standard input when using install
  --force             Replace an existing token without confirmation
  --help              Show this help

Examples:
  backeer-opencode configure
  backeer-opencode install --token-file /run/secrets/backeer-token

If install has no token option, an existing token is preserved.`)
  process.exit(exitCode)
}

function parseArguments(arguments_) {
  const remaining = [...arguments_]
  let command = "install"
  if (["configure", "install", "status"].includes(remaining[0])) {
    command = remaining.shift()
  }

  const result = { command }
  for (let index = 0; index < remaining.length; index++) {
    const argument = remaining[index]
    if (argument === "--help") usage()
    if (argument === "--token-stdin") {
      result.tokenStdin = true
      continue
    }
    if (argument === "--force") {
      result.force = true
      continue
    }
    if (argument === "--config-dir" || argument === "--token-file") {
      const value = remaining[++index]
      if (!value) usage(1)
      result[argument === "--config-dir" ? "configDir" : "tokenFile"] = value
      continue
    }
    console.error(`Unknown option: ${argument}`)
    usage(1)
  }
  if (result.tokenStdin && result.tokenFile) {
    throw new Error("Use either --token-stdin or --token-file, not both")
  }
  if (command === "configure" && (result.tokenStdin || result.tokenFile)) {
    throw new Error("configure prompts securely; do not use token input options")
  }
  if (command === "install" && result.force) {
    throw new Error("--force is supported only by configure")
  }
  return result
}

function defaultConfigDirectory() {
  const base = process.env.XDG_CONFIG_HOME?.trim()
  return base ? join(base, "opencode") : join(homedir(), ".config", "opencode")
}

function writeSecretAtomically(path, token) {
  if (!token) throw new Error("The Backeer ingest token is empty")
  mkdirSync(dirname(path), { recursive: true, mode: 0o700 })
  const temporaryPath = `${path}.${process.pid}.tmp`
  writeFileSync(temporaryPath, `${token}\n`, { encoding: "utf8", mode: 0o600 })
  chmodSync(temporaryPath, 0o600)
  renameSync(temporaryPath, path)
}

async function confirmReplacement(secretPath) {
  if (!existsSync(secretPath) || statSync(secretPath).size === 0) return true
  if (!process.stdin.isTTY || !process.stdout.isTTY) {
    throw new Error(
      `A token already exists at ${secretPath}; rerun in a terminal or use --force`,
    )
  }

  const prompt = createInterface({ input: process.stdin, output: process.stdout })
  try {
    const answer = await prompt.question(
      `A Backeer token already exists at ${secretPath}. Replace it? [y/N] `,
    )
    return ["y", "yes"].includes(answer.trim().toLowerCase())
  } finally {
    prompt.close()
  }
}

function readHiddenToken() {
  const input = process.stdin
  const output = process.stdout
  if (!input.isTTY || !output.isTTY || typeof input.setRawMode !== "function") {
    throw new Error("Interactive token entry requires a terminal")
  }

  return new Promise((resolvePromise, rejectPromise) => {
    let token = ""
    const wasRaw = input.isRaw === true
    output.write("Backeer source ingest token: ")
    input.setEncoding("utf8")
    input.setRawMode(true)
    input.resume()

    function cleanup() {
      input.removeListener("data", onData)
      input.setRawMode(wasRaw)
      if (!wasRaw) input.pause()
      output.write("\n")
    }

    function onData(chunk) {
      for (const character of chunk) {
        if (character === "\u0003") {
          cleanup()
          rejectPromise(new Error("Token configuration cancelled"))
          return
        }
        if (character === "\r" || character === "\n") {
          cleanup()
          resolvePromise(token.trim())
          return
        }
        if (character === "\u007f" || character === "\b") {
          token = token.slice(0, -1)
          continue
        }
        if (character >= " ") token += character
      }
    }

    input.on("data", onData)
  })
}

async function configureToken(secretPath, force) {
  if (!force && !(await confirmReplacement(secretPath))) {
    console.log("Backeer token unchanged.")
    return
  }

  const token = await readHiddenToken()
  writeSecretAtomically(secretPath, token)
  console.log(`Configured protected Backeer token: ${secretPath}`)
  console.log("Restart OpenCode to use the new token.")
}

const arguments_ = parseArguments(process.argv.slice(2))
const configDirectory = resolve(arguments_.configDir ?? defaultConfigDirectory())
const pluginDirectory = join(configDirectory, "plugins")
const secretPath = join(configDirectory, "secrets", "backeer-ingest-token")
const packageDirectory = resolve(dirname(fileURLToPath(import.meta.url)), "..")
const sourcePath = join(packageDirectory, "dist", "backeer-permission.js")
// Keep the legacy filename so upgrading an existing Backeer installation
// replaces it instead of loading two copies of the same plugin.
const installedPath = join(pluginDirectory, "backeer-permission.js")

try {
  if (process.argv[2] === "status") {
    if (process.argv.length !== 3) throw new Error("Usage: backeer-opencode status (run in the intended project directory)")
    const { OpenCode } = await import("@opencode/client")
    const { Service } = await import("@opencode/client/service")
    const { LIVE_STATUS_RPC } = await import("../src/live-status.js")
    const { formatLocalReport } = await import("../src/live-report.js")
    const endpoint = await Service.discover()
    if (!endpoint) throw new Error("The existing native OpenCode service is unavailable; no service was started.")
    const client = OpenCode.make({ baseUrl: endpoint.url, headers: Service.headers(endpoint) })
    const report = await client.rpc(LIVE_STATUS_RPC).diagnostics({}, { location: { directory: process.cwd() } })
    console.log(formatLocalReport(report))
    process.exit(0)
  }
  if (arguments_.command === "configure") {
    await configureToken(secretPath, arguments_.force)
  } else {
    mkdirSync(pluginDirectory, { recursive: true })
    copyFileSync(sourcePath, installedPath)
    chmodSync(installedPath, 0o644)

    if (arguments_.tokenFile) {
      writeSecretAtomically(
        secretPath,
        readFileSync(resolve(arguments_.tokenFile), "utf8").trim(),
      )
    } else if (arguments_.tokenStdin) {
      writeSecretAtomically(secretPath, readFileSync(0, "utf8").trim())
    }

    console.log(`Installed Backeer OpenCode plugin: ${installedPath}`)
    console.log(
      arguments_.tokenFile || arguments_.tokenStdin
        ? `Installed protected ingest token: ${secretPath}`
        : `Token unchanged; expected at ${secretPath} or in BACKEER_INGEST_TOKEN`,
    )
    console.log("Restart OpenCode to load the plugin.")
  }
} catch (error) {
  console.error(`Backeer configuration failed: ${error.message}`)
  process.exitCode = 1
}

