import { setup } from "./opencode-v2.js"

// A plain definition avoids an authoring-SDK dependency in the installer bundle.
// OpenCode >=1.18.29 calls server(); OpenCode V2 calls setup().
export default { id: "backeer-opencode", setup, server }

import { stableHash } from "./utilities.js"
