/**
 * OpenCode server plugin entrypoint.
 *
 * Supported options: origin, tokenFile, permissions, questions, todos,
 * lifecycle, liveBridge, logLevel.
 * The ingest token is intentionally accepted only through the environment or a
 * protected file so it cannot accidentally be committed in opencode.json.
 */
export default async function BackeerPlugin({ client, directory, feedback, v2 = false, liveStatus, notificationsDelegated = false }, options = {}) {
  const bootstrapReporter = createOpenCodeReporter(
    client,
    options.logLevel ?? process.env.BACKEER_LOG_LEVEL,
  )
  let config
  try {
    config = loadConfig(options)
  } catch (error) {
    bootstrapReporter.error("Plugin disabled — invalid configuration", error)
    return {}
  }

  const shutdown = new AbortController()
  config.signal = shutdown.signal
  const reporter = createOpenCodeReporter(client, config.logLevel)
  const conversation = feedback ?? createConversationFeedback({ client, reporter })
  if (config.liveBridge.error) reporter.error("Live control disabled", config.liveBridge.error)
  const delegated = config.liveBridge.owner === "tui" ||
    (config.liveBridge.owner === "standalone" && (!v2 || !process.argv.includes("--stdio")))
  const liveBridge = await superviseLiveBridge({ config, client, directory, reporter, status: liveStatus, delegated })

  const permissionController = createPermissionController({
    config,
    reporter,
    client,
    directory,
    conversation,
    onAutomaticallyAllowed: (identity, request) => {
      if (config.token && config.permissions && !shutdown.signal.aborted) {
        return publishAutomaticPermission(config, reporter, request, directory, identity)
      }
    },
  })
  if (config.token && !notificationsDelegated) config.notificationOutbox = createNotificationDispatcher(config, {
    scope: directory, reporter,
    onResult: (event, error) => {
      if (event.externalId?.startsWith("opencode:") && !event.externalId.endsWith(":automatic")) {
        permissionPublications[error ? "fail" : "succeed"](event.externalId)
      }
      const sessionID = /^opencode-todo:([^:]+):/.exec(event.externalId ?? "")?.[1]
      const pending = pendingTodoReceipts.get(sessionID)
      if (pending?.externalId === event.externalId) {
        todoCompletions[error ? "fail" : "succeed"](pending.attempt)
        pendingTodoReceipts.delete(sessionID)
      }
    },
    send: (snapshot, url, body, signal) => postJsonWithRetry(snapshot, url, body, { signal, bypassOutbox: true, retryDelays: [0] }),
  })
  const questionPublicationsInFlight = new Map()
  const pendingTodoReceipts = new Map()
  const lifecycleController = createLifecycleController({
    config,
    reporter,
    client,
    directory,
    conversation,
  })
  const permissionPublications = createDeliveryTracker()
  const questionPublications = createDeliveryTracker()
  const todoCompletions = createCompletionTracker()
  // Resume persisted notifications even when no new native event occurs.
  await config.notificationOutbox?.start().catch(error => reporter.error("Notification queue could not be started", error))
  const updateChecker = createUpdateChecker({ v2 })
  const handleBackeerCommand = createBackeerCommandHandler({
    client,
    config,
    permissionController,
    reporter,
    updateChecker,
  })
  const handleUpdateNotice = createUpdateNoticeHook(updateChecker)

  if (!config.token && !notificationsDelegated) {
    reporter.error(
      "Notifications disabled — use /backeer token",
      `Token not found at ${config.tokenFile}`,
    )
  }

  async function handlePermissionAsked(event) {
    const identity = permissionIdentity(event.properties)
    if (!identity) {
      reporter.error("Permission event is missing correlation IDs")
      return
    }
    permissionController.register(identity)
    if (!permissionPublications.begin(identity.externalId)) return

    await publishPermission(
      config,
      reporter,
      event.properties,
      directory,
      identity,
      conversation,
    ).then(result => { if (!result?.queued) permissionPublications.succeed(identity.externalId) })
      .catch((error) => {
        permissionPublications.fail(identity.externalId)
        reporter.error("Permission request could not be sent", error)
        conversation.error(identity.sessionID, "Permission request could not be sent")
      })
  }

  async function handleTodoUpdated(event) {
    const { sessionID, todos } = event.properties
    if (typeof sessionID !== "string" || !Array.isArray(todos)) {
      reporter.error("Todo event is missing a valid session or list")
      return
    }

    const isComplete = todos.length > 0 &&
      todos.every((todo) => todo?.status === "completed")
    const attempt = todoCompletions.update(sessionID, isComplete)
    if (!attempt) return

    const correlation = typeof event.id === "string" && event.id ? event.id : stableHash(JSON.stringify(todos))
    pendingTodoReceipts.set(sessionID, { externalId: `opencode-todo:${sessionID}:${correlation}`, attempt })
    await publishTodoCompletion(
      config,
      reporter,
      event.properties,
      event.id,
      client,
      directory,
      conversation,
    ).then(result => { if (!result?.queued) { todoCompletions.succeed(attempt); pendingTodoReceipts.delete(sessionID) } })
      .catch((error) => {
        todoCompletions.fail(attempt)
        reporter.error("Todo completion could not be sent", error)
        conversation.error(sessionID, "Todo completion could not be sent")
      })
  }

  async function handleQuestionAsked(event) {
    const identity = questionIdentity(event.properties)
    if (!identity) {
      reporter.error("Question event is missing correlation IDs")
      return
    }
    if (!questionPublications.begin(identity.externalId)) return

    const publication = new AbortController()
    const abort = () => publication.abort()
    shutdown.signal.addEventListener("abort", abort, { once: true })
    questionPublicationsInFlight.set(identity.requestID, publication)
    void publishQuestion(
      Object.assign(Object.create(config), { signal: publication.signal }),
      reporter,
      event.properties,
      identity,
      client,
      directory,
      conversation,
      event.type,
    ).then((eventID) => {
      questionPublications.succeed(identity.externalId)
      if (eventID) {
        permissionController.registerQuestion(identity, {
          eventID,
          sourceEvent: event.type,
          questions: event.properties.questions,
        })
      }
    })
      .catch((error) => {
        questionPublications.fail(identity.externalId)
        reporter.error("Question could not be sent", error)
        if (!publication.signal.aborted) conversation.error(identity.sessionID, "Question could not be sent")
      }).finally(() => {
        shutdown.signal.removeEventListener("abort", abort)
        if (questionPublicationsInFlight.get(identity.requestID) === publication) questionPublicationsInFlight.delete(identity.requestID)
      })
  }

  async function handleNotificationEvent(event) {
    // Native filesystem approvals are independent of the mobile notification
    // token and its permissions switch. Reply only to the exact native request.
    if (event.type === "permission.asked") {
      const identity = permissionIdentity(event.properties ?? {})
      if (identity && await permissionController.automaticallyAllowFilesystem(identity, event.properties)) return
    }
    if (shutdown.signal.aborted) return
    if (event.type === "permission.replied") {
      permissionController.resolveLocally(
        event.properties?.requestID ?? event.properties?.id, event.properties?.sessionID,
      )
    }
    if (!config.token) return

    conversation.handle(event)
    await lifecycleController.handle(event)

    if (config.permissions && event.type === "permission.asked") {
      await handlePermissionAsked(event)
      return
    }

    if (config.permissions && event.type === "permission.replied") {
      return
    }

    if (config.todos && event.type === "todo.updated") {
      await handleTodoUpdated(event)
      return
    }

    if (
      config.questions &&
      (event.type === "question.asked" || event.type === "question.v2.asked")
    ) {
      await handleQuestionAsked(event)
      return
    }

    if (
      config.questions &&
      ["question.replied", "question.v2.replied", "question.rejected", "question.v2.rejected"]
        .includes(event.type)
    ) {
      const requestID = event.properties.requestID ?? event.properties.id
      if (typeof requestID === "string") {
        questionPublicationsInFlight.get(requestID)?.abort()
        questionPublicationsInFlight.delete(requestID)
        permissionController.resolveQuestionLocally(
          requestID,
          event.type.endsWith("rejected") ? "rejected" : "answered",
        )
      }
    }
  }

  return {
    config: async (opencodeConfig) => {
      registerBackeerCommand(opencodeConfig)
    },
    "command.execute.before": handleBackeerCommand,
    "chat.message": handleUpdateNotice,
    sourceGap: () => liveBridge.gap("native_source_interrupted"),
    event: async ({ event }) => {
      if (shutdown.signal.aborted) return
      // Start existing mobile handling first; live lookups must not gate approvals.
      await Promise.all([notificationsDelegated ? undefined : handleNotificationEvent(event), liveBridge.handle(event)])
    },
    dispose: async () => {
      shutdown.abort()
      for (const publication of questionPublicationsInFlight.values()) publication.abort()
      questionPublicationsInFlight.clear()
      pendingTodoReceipts.clear()
      await config.notificationOutbox?.close()
      config.liveBridgeState = "stopped"
      await liveBridge.dispose()
      await permissionController.dispose()
      lifecycleController.dispose()
      permissionPublications.clear()
      questionPublications.clear()
      todoCompletions.clear()
      conversation.dispose()
    },
  }
}
